//! `lunepack publish refresh`, `plan` and `init`: the real binary over `--store-dir`. Keys are
//! generated by the binary at test time. The commit-order, race and MemStore-log cases of the same
//! commands are unit tests in `src/cmd_publish/{refresh,plan}.rs`.

mod common;
#[path = "common/publish.rs"]
mod publish;

use std::fs;
use std::path::Path;
use std::process::Output;

use common::*;
use publish::*;

const PENDING: &str = "lunepack-pending-deletes.json";

impl Fixture {
    fn command(&self, config: &Path, command: &str, args: &[&str], store: &Path) -> Output {
        let mut all = vec!["--config", s(config), "publish", command];
        all.extend_from_slice(args);
        all.extend_from_slice(&["--store-dir", s(store)]);
        self.run_plain(&all, &[])
    }

    fn refresh(&self, config: &Path, store: &Path, extra: &[&str]) -> Output {
        let sign = format!("file:{}", s(&self.release_signer));
        let mut args = vec!["--sign", sign.as_str()];
        args.extend_from_slice(extra);
        self.command(config, "refresh", &args, store)
    }

    fn plan(&self, config: &Path, store: &Path, extra: &[&str]) -> Output {
        self.command(config, "plan", extra, store)
    }

    /// Publishes `version` into `store` (fetch's copy of the public bucket, pack, push).
    fn publish(&self, config: &Path, store: &Path, version: &str) {
        let rd = self.release_dir(&format!("rd-{version}"), &public_of(store), version);
        let out = self.push(config, &rd, version, &["--store-dir", s(store)], &[]);
        assert_ok(&out, "push");
    }
}

fn feed_seq(plan_output: &str) -> u64 {
    let rest = plan_output
        .lines()
        .find_map(|l| l.strip_prefix("feed-stable.json: seq "))
        .unwrap_or_else(|| panic!("no feed line in {plan_output}"));
    rest.split(',').next().unwrap().parse().unwrap()
}

/// The keys of `a` and `b` whose bytes differ or that exist in one only.
fn changed(
    a: &std::collections::BTreeMap<String, Vec<u8>>,
    b: &std::collections::BTreeMap<String, Vec<u8>>,
) -> Vec<String> {
    a.keys()
        .chain(b.keys())
        .filter(|k| a.get(*k) != b.get(*k))
        .cloned()
        .collect::<std::collections::BTreeSet<_>>()
        .into_iter()
        .collect()
}

fn pack_rel() -> String {
    format!("{P}/1.0.0/{}.pack", target())
}

#[test]
fn refresh_re_signs_every_feed_and_a_fresh_feed_needs_no_refresh() {
    let (f, origin) = Fixture::new(now() - 3600);
    let config = f.r2_config_keeping(5);
    let store = f.store_dir(&origin);
    f.publish(&config, &store, "1.0.0");
    f.publish(&config, &store, "1.1.0");
    let out = f.plan(&config, &store, &[]);
    assert_ok(&out, "plan");
    let before_plan = stdout(&out);
    assert!(
        before_plan.contains("2 release(s): 1.1.0, 1.0.0"),
        "{before_plan}"
    );
    let seq0 = feed_seq(&before_plan);

    // No feed expires within 7 days (a feed lives 90): nothing is written.
    let before = tree(&store);
    let out = f.refresh(&config, &store, &["--if-expiring-within-days", "7"]);
    assert_ok(&out, "refresh, nothing due");
    assert!(
        stdout(&out).contains("nothing to refresh: no feed expires within 7 day(s)"),
        "{}",
        stdout(&out)
    );
    assert!(tree(&store) == before, "a refresh with nothing due wrote");

    // A dry run does every read and check and writes nothing.
    let out = f.refresh(&config, &store, &["--dry-run"]);
    assert_ok(&out, "dry run");
    let text = stdout(&out);
    assert!(
        text.contains(&format!("would write: {P}/feed-stable.json")),
        "{text}"
    );
    assert!(text.contains("dry run: nothing was written"), "{text}");
    assert!(tree(&store) == before, "a dry run wrote");

    // Every feed: the releases stay, the seq rises, and only the public feed changes (S1: a refresh
    // never writes the private bucket).
    let out = f.refresh(&config, &store, &[]);
    assert_ok(&out, "refresh");
    assert!(
        stdout(&out).contains("refreshed: 1 feed(s)"),
        "{}",
        stdout(&out)
    );
    let after = tree(&store);
    assert_eq!(
        changed(&before, &after),
        [format!("public/{P}/feed-stable.json")]
    );
    let out = f.plan(&config, &store, &[]);
    assert_ok(&out, "plan after");
    let after_plan = stdout(&out);
    assert!(
        after_plan.contains("2 release(s): 1.1.0, 1.0.0"),
        "{after_plan}"
    );
    assert!(feed_seq(&after_plan) > seq0, "{after_plan}");

    // A feed that expires within 100 days is due (it lives 90).
    let seq1 = feed_seq(&after_plan);
    let out = f.refresh(&config, &store, &["--if-expiring-within-days", "100"]);
    assert_ok(&out, "refresh, due");
    assert!(stdout(&out).contains("refreshed: 1 feed(s)"));
    let out = f.plan(&config, &store, &[]);
    assert!(feed_seq(&stdout(&out)) > seq1);
}

#[test]
fn skip_if_unpublished_is_exit_0_with_one_notice_and_without_it_exit_1() {
    let (f, origin) = Fixture::new(now() - 3600);
    let config = f.r2_config();

    // Nothing at all in the store.
    let empty = f.dir.path().join("empty-store");
    fs::create_dir_all(empty.join("public")).unwrap();
    fs::create_dir_all(empty.join("private")).unwrap();
    let out = f.refresh(&config, &empty, &["--skip-if-unpublished"]);
    assert_ok(&out, "skip, empty store");
    let notices: Vec<_> = stdout(&out)
        .lines()
        .filter(|l| l.starts_with("notice:"))
        .map(str::to_owned)
        .collect();
    assert_eq!(notices.len(), 1, "{}", stdout(&out));
    assert!(tree(&empty).is_empty());
    let err = assert_fails(&f.refresh(&config, &empty, &[]), 1, "no flag, empty store");
    assert!(err.contains("publish init"), "{err}");

    // Documents but no feed.
    let store = f.store_dir(&origin);
    let before = tree(&store);
    let out = f.refresh(&config, &store, &["--skip-if-unpublished"]);
    assert_ok(&out, "skip, no feed");
    assert!(
        stdout(&out).contains("notice: nothing to refresh: the public bucket has no feed yet"),
        "{}",
        stdout(&out)
    );
    assert!(tree(&store) == before);
    let err = assert_fails(&f.refresh(&config, &store, &[]), 1, "no flag, no feed");
    assert!(err.contains("no feed to refresh"), "{err}");
    assert!(tree(&store) == before);
}

#[test]
fn a_refresh_leaves_the_pending_record_and_its_objects_to_the_next_push() {
    let (f, origin) = Fixture::new(now() - 3600);
    let config = f.r2_config();
    let store = f.store_dir(&origin);
    f.publish(&config, &store, "1.0.0");
    // The record names a listed version's pack (a version re-listed or never dropped) and an
    // object of a version that no feed lists.
    let old = store.join("public").join(P).join("0.9.0");
    fs::create_dir_all(&old).unwrap();
    fs::write(old.join("x.pack"), b"old").unwrap();
    let record = format!(
        "{{\"format\":1,\"keys\":[\"{P}/0.9.0/x.pack\",\"{}\"],\"uploading\":[]}}\n",
        pack_rel()
    );
    fs::write(store.join("private").join(P).join(PENDING), &record).unwrap();
    let before = tree(&store);

    // Nothing due: nothing is written, and the notice says who runs the deletes.
    let out = f.refresh(&config, &store, &["--if-expiring-within-days", "7"]);
    assert_ok(&out, "refresh");
    let text = stdout(&out);
    assert!(
        text.contains("2 pending delete(s) are left to the next `publish push`"),
        "{text}"
    );
    assert!(!text.contains("deleted:"), "{text}");
    assert!(tree(&store) == before);

    // Re-signing: the feed changes, the record and the objects do not.
    assert_ok(&f.refresh(&config, &store, &[]), "refresh, due");
    assert!(old.join("x.pack").exists());
    assert!(store.join("public").join(pack_rel()).is_file());
    assert_eq!(
        fs::read(store.join("private").join(P).join(PENDING)).unwrap(),
        record.as_bytes()
    );
    assert_eq!(
        changed(&before, &tree(&store)),
        [format!("public/{P}/feed-stable.json")]
    );
}

#[test]
fn plan_writes_nothing_and_names_what_a_push_would_do_and_any_abandoned_push() {
    let (f, origin) = Fixture::new(now() - 3600);
    let config = f.r2_config();
    let store = f.store_dir(&origin);
    f.publish(&config, &store, "1.0.0");
    let before = tree(&store);

    let out = f.plan(&config, &store, &["--version", "1.1.0"]);
    assert_ok(&out, "plan 1.1.0");
    let text = stdout(&out);
    assert!(
        text.contains("push 1.1.0: feed-stable.json: add 1.1.0; drop 1.0.0"),
        "{text}"
    );
    assert!(text.contains("pending deletes: none"), "{text}");
    assert!(text.contains("plan: nothing was written"), "{text}");
    let out = f.plan(&config, &store, &["--version", "1.0.0"]);
    assert!(
        stdout(&out).contains("push 1.0.0: feed-stable.json: already lists 1.0.0"),
        "{}",
        stdout(&out)
    );
    let out = f.plan(&config, &store, &["--version", "1.2.0-rc.1"]);
    assert!(stdout(&out).contains("add 1.2.0-rc.1"), "{}", stdout(&out));
    assert_fails(
        &f.plan(&config, &store, &["--version", "1.0"]),
        2,
        "bad version",
    );
    assert!(tree(&store) == before, "plan wrote");

    // An abandoned push: 1.1.0's objects are in the store, the record marks it uploading, and no
    // feed lists it.
    let rd = f.release_dir("rd-1.1.0", &public_of(&store), "1.1.0");
    let dest = store.join("public").join(P).join("1.1.0");
    fs::create_dir_all(&dest).unwrap();
    for entry in fs::read_dir(rd.join("1.1.0")).unwrap() {
        let path = entry.unwrap().path();
        fs::copy(&path, dest.join(path.file_name().unwrap())).unwrap();
    }
    let stale = format!(
        "{{\"format\":1,\"keys\":[\"{}\"],\"uploading\":[\"1.1.0\"]}}\n",
        pack_rel()
    );
    fs::write(store.join("private").join(P).join(PENDING), stale).unwrap();
    let before = tree(&store);
    let out = f.plan(&config, &store, &[]);
    assert_ok(&out, "plan with an abandoned push");
    let text = stdout(&out);
    assert!(text.contains("abandoned: 1.1.0"), "{text}");
    assert!(text.contains("pending deletes: 1 key(s)"), "{text}");
    assert!(
        text.contains(&format!("  {P}/1.1.0/{}.manifest.json", target())),
        "{text}"
    );
    assert!(
        text.contains(&format!("  {P}/1.1.0/{}.pack", target())),
        "{text}"
    );
    assert!(tree(&store) == before, "plan wrote");

    // An unpublished store is an error naming `publish init`.
    let empty = f.dir.path().join("empty-store");
    let err = assert_fails(&f.plan(&config, &empty, &[]), 1, "plan, no store");
    assert!(err.contains("publish init"), "{err}");
}

#[test]
fn init_uploads_roots_then_keys_then_state_and_refuses_an_existing_document() {
    let (mut f, origin) = Fixture::new(now() - 3600);
    let config = f.r2_config();
    let fresh = f.dir.path().join("fresh");

    // A dry run does every check and writes nothing.
    let origin_arg = s(&origin).to_owned();
    let out = f.command(
        &config,
        "init",
        &["--release-dir", &origin_arg, "--dry-run"],
        &fresh,
    );
    assert_ok(&out, "init dry run");
    let text = stdout(&out);
    assert!(
        text.contains(&format!("would upload: {P}/keys.json")),
        "{text}"
    );
    assert!(
        text.contains(&format!("would upload: {P}/lunepack-state.json")),
        "{text}"
    );
    assert!(tree(&fresh).is_empty());

    // A rotated root: root-2.json goes first.
    let (next, next_public) = f.generate("root2");
    let old = format!("file:{}", s(&f.root));
    let new = format!("file:{}", s(&next));
    let out = f.run(
        &[
            "--config",
            s(&f.pack_config),
            "keys",
            "rotate-root",
            "--release-dir",
            &origin_arg,
            "--new-root-key",
            &next_public,
            "--new-threshold",
            "1",
            "--sign",
            &old,
            "--sign-new",
            &new,
        ],
        &[],
    );
    assert_ok(&out, "rotate-root");
    assert!(origin.join("root-2.json").is_file());

    // The store already holds the root: named first, nothing written.
    let taken = f.dir.path().join("taken");
    fs::create_dir_all(taken.join("public").join(P)).unwrap();
    fs::write(taken.join("public").join(P).join("root-2.json"), b"x").unwrap();
    let before = tree(&taken);
    let out = f.command(&config, "init", &["--release-dir", &origin_arg], &taken);
    let err = assert_fails(&out, 1, "existing root");
    assert!(
        err.contains(&format!("already holds {P}/root-2.json")),
        "{err}"
    );
    assert!(tree(&taken) == before);

    let out = f.command(&config, "init", &["--release-dir", &origin_arg], &fresh);
    assert_ok(&out, "init");
    let uploaded: Vec<String> = stdout(&out)
        .lines()
        .filter_map(|l| l.strip_prefix("uploaded: "))
        .map(str::to_owned)
        .collect();
    assert_eq!(
        uploaded,
        [
            format!("{P}/root-2.json"),
            format!("{P}/keys.json"),
            format!("{P}/lunepack-state.json")
        ]
    );
    assert_eq!(
        fs::read(fresh.join("public").join(P).join("keys.json")).unwrap(),
        fs::read(origin.join("keys.json")).unwrap()
    );
    assert_eq!(
        fs::read(fresh.join("private").join(P).join("lunepack-state.json")).unwrap(),
        f.state()
    );

    // The store now holds them: a second init names the first.
    let before = tree(&fresh);
    let out = f.command(&config, "init", &["--release-dir", &origin_arg], &fresh);
    let err = assert_fails(&out, 1, "second init");
    assert!(
        err.contains(&format!("already holds {P}/root-2.json")),
        "{err}"
    );
    assert!(tree(&fresh) == before);

    // Only the state file exists: it is named, and no public document is written.
    let state_only = f.dir.path().join("state-only");
    fs::create_dir_all(state_only.join("private").join(P)).unwrap();
    fs::write(
        state_only
            .join("private")
            .join(P)
            .join("lunepack-state.json"),
        b"{}",
    )
    .unwrap();
    let out = f.command(
        &config,
        "init",
        &["--release-dir", &origin_arg],
        &state_only,
    );
    let err = assert_fails(&out, 1, "existing state");
    assert!(
        err.contains(&format!("already holds {P}/lunepack-state.json")),
        "{err}"
    );
    assert!(!state_only.join("public").exists());

    // A directory without keys.json is a usage error.
    let none = f.dir.path().join("no-keys");
    fs::create_dir(&none).unwrap();
    let out = f.command(&config, "init", &["--release-dir", s(&none)], &fresh);
    assert_fails(&out, 2, "no keys.json");
}

#[test]
fn source_date_epoch_is_refused_by_refresh_init_and_keys_and_not_by_plan() {
    let (f, origin) = Fixture::new(now() - 3600);
    let config = f.r2_config();
    let store = f.store_dir(&origin);
    f.publish(&config, &store, "1.0.0");
    let sign = format!("file:{}", s(&f.release_signer));
    let before = tree(&store);
    let epoch = [("SOURCE_DATE_EPOCH", f.epoch.as_str())];
    let store_arg = s(&store).to_owned();
    for args in [
        vec![
            "publish",
            "refresh",
            "--sign",
            &sign,
            "--store-dir",
            &store_arg,
        ],
        vec![
            "publish",
            "init",
            "--release-dir",
            s(&origin),
            "--store-dir",
            &store_arg,
        ],
        vec![
            "publish",
            "keys",
            "--release-dir",
            s(&origin),
            "--store-dir",
            &store_arg,
        ],
    ] {
        let mut all = vec!["--config", s(&config)];
        all.extend_from_slice(&args);
        let out = f.run_plain(&all, &epoch);
        let err = assert_fails(&out, 1, args[1]);
        assert!(err.contains("SOURCE_DATE_EPOCH is set"), "{err}");
        assert!(stdout(&out).is_empty(), "{}", stdout(&out));
    }
    assert!(tree(&store) == before);
    let out = f.run_plain(
        &[
            "--config",
            s(&config),
            "publish",
            "plan",
            "--store-dir",
            &store_arg,
        ],
        &epoch,
    );
    assert_ok(&out, "plan is exempt");
}
